        const wingRows=(capacity.wings||[]).map(row=>`<li>${esc(row.wing||'Unassigned wing')} · workflow ${esc(row.workflow_hours??'Unknown')}h · ${esc((row.assigned_person_ids||[]).length)} assigned</li>`).join('');
