// Lightweight post-render Brain customization history/actions enhancement.
(function(){
  const enrich=async()=>{const section=document.querySelector('[data-brain-customizations]');if(!section||section.querySelector('[data-brain-history]'))return;const note=document.createElement('p');note.dataset.brainHistory='1';note.className='source-note';note.textContent='Version history is available only to identities granted brain_configure.';section.appendChild(note);try{const settings=await api(`/dashboard/settings?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace||'')}`),data=settings.brain_customization||{};const history=document.createElement('details');history.dataset.brainHistory='1';history.innerHTML=`<summary>Version history (${esc((data.versions||[]).length)})</summary><ul>${(data.versions||[]).map(x=>`<li>${esc(x.name||x.kind||x.id)} · v${esc(x.version||'Unknown')} ${data.can_manage?`<button class="ghost" data-brain-activate="${esc(x.id)}" type="button">Activate</button><button class="ghost" data-brain-rollback="${esc(x.id)}" type="button">Rollback</button>`:''}</li>`).join('')||'<li>No versions recorded.</li>'}</ul>`;section.appendChild(history);if(!data.can_manage)return;const actions=document.createElement('div');actions.className='row';actions.innerHTML='<button class="ghost" type="button" data-brain-create>New version</button>';section.appendChild(actions);const apply=async(button,route)=>{const id=button.dataset.brainActivate||button.dataset.brainRollback;try{await api(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization_id:org,version_id:route.endsWith('activate')?id:undefined,target_version_id:route.endsWith('rollback')?id:undefined,reason:'Dashboard customization action'})});location.reload()}catch(error){toast(`Customization unavailable · ${error.message}`)}};history.querySelectorAll('[data-brain-activate]').forEach(b=>b.onclick=()=>apply(b,'/brain/customizations/activate'));history.querySelectorAll('[data-brain-rollback]').forEach(b=>b.onclick=()=>apply(b,'/brain/customizations/rollback'));actions.querySelector('[data-brain-create]').onclick=async()=>{const name=prompt('Version name'),body=name&&prompt('Instruction body');if(!name||!body)return;try{await api('/brain/customizations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization_id:org,workspace_id:workspace||null,scope_type:workspace?'workspace':'organization',kind:'instructions',name,body,reason:'Dashboard version creation'})});location.reload()}catch(error){toast(`Customization unavailable · ${error.message}`)}}}catch(_){/* Settings remains truthful when schema/capability is unavailable. */}};
  setInterval(enrich,1200);
})();
